// Sprite atlases generated by `pnpm sprites` (tools/build-sprites.ts → public/atlases/<name>.png|json, Pixi
// Spritesheet format, frame names per assets-src/gen/lib/types.ts) and listed in public/atlases/index.json.
// Loaded before the first frame, so `body[data-ready="1"]` implies every atlas is loaded. Any missing or
// malformed atlas rejects with an error (startWorld then marks the page `data-ready="error"`).
import { Assets, Spritesheet, type Texture } from 'pixi.js';

/** One entry of public/atlases/index.json (tools/lib/sprites/atlas.ts `AtlasIndex`). */
interface AtlasEntry {
  readonly name: string;
  readonly json: string;
  /** Dev/test-only atlas (e.g. `debug`): skipped in production, where the file is not shipped either. */
  readonly debug: boolean;
}

export type Atlases = ReadonlyMap<string, Spritesheet>;

const ATLAS_DIR = `${import.meta.env.BASE_URL}atlases/`;
const FILE = /^[a-z][a-z0-9-]*\.json$/;

let configured = false;

// A guard (not a bare instanceof) so the narrowed type is Spritesheet<SpritesheetData>, not Spritesheet<any>.
const isSpritesheet = (value: unknown): value is Spritesheet => value instanceof Spritesheet;

function parseIndex(json: unknown): AtlasEntry[] {
  const list = typeof json === 'object' && json !== null ? (json as { atlases?: unknown }).atlases : undefined;
  if (!Array.isArray(list)) throw new Error('atlases/index.json: missing "atlases" list');
  return list.map((raw: unknown, i) => {
    const e = (typeof raw === 'object' && raw !== null ? raw : {}) as Partial<Record<keyof AtlasEntry, unknown>>;
    if (
      typeof e.name !== 'string' ||
      typeof e.json !== 'string' ||
      !FILE.test(e.json) ||
      typeof e.debug !== 'boolean'
    ) {
      throw new Error(`atlases/index.json: bad entry ${String(i)}`);
    }
    return { name: e.name, json: e.json, debug: e.debug };
  });
}

export async function loadAtlases(): Promise<Atlases> {
  if (!configured) {
    // CSP (M0-12): Pixi's default image loader runs in a Worker built from a blob: URL, which a strict
    // `script-src 'self'` blocks. Decode on the main thread instead (fetch + createImageBitmap).
    Assets.setPreferences({ preferWorkers: false });
    configured = true;
  }
  const response = await fetch(`${ATLAS_DIR}index.json`);
  if (!response.ok) throw new Error(`atlases/index.json: HTTP ${String(response.status)} — run \`pnpm sprites\``);
  const entries = parseIndex(await response.json()).filter((e) => __CK_DEBUG__ || !e.debug);

  const atlases = new Map<string, Spritesheet>();
  await Promise.all(
    entries.map(async (entry) => {
      const sheet: unknown = await Assets.load(`${ATLAS_DIR}${entry.json}`);
      if (!isSpritesheet(sheet)) throw new Error(`atlas "${entry.name}" is not a spritesheet`);
      atlases.set(entry.name, sheet);
    }),
  );
  return atlases;
}

/** Frame texture by name; a missing atlas or frame is a build/content bug, so it throws. */
export function frame(atlases: Atlases, atlas: string, name: string): Texture {
  const sheet = atlases.get(atlas);
  if (!sheet) throw new Error(`atlas "${atlas}" is not loaded — run \`pnpm sprites\``);
  const texture = sheet.textures[name];
  if (!texture) throw new Error(`atlas "${atlas}" has no frame "${name}" — run \`pnpm sprites\``);
  return texture;
}
